import re

def cmp_semver(a, b):
    def parse(v):
        v = v.split('+')[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        major, minor, patch = map(int, core.split('.'))
        pre_parts = pre.split('.') if pre else []
        return (major, minor, patch, pre_parts)

    a_parsed = parse(a)
    b_parsed = parse(b)

    for i in range(3):
        if a_parsed[i] < b_parsed[i]:
            return -1
        elif a_parsed[i] > b_parsed[i]:
            return 1

    a_pre, b_pre = a_parsed[3], b_parsed[3]
    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1
    if not b_pre:
        return -1

    for i in range(max(len(a_pre), len(b_pre))):
        if i >= len(a_pre):
            return -1
        if i >= len(b_pre):
            return 1
        a_id, b_id = a_pre[i], b_pre[i]
        a_num = a_id.isdigit()
        b_num = b_id.isdigit()
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        if a_num and b_num:
            a_num, b_num = int(a_id), int(b_id)
            if a_num < b_num:
                return -1
            elif a_num > b_num:
                return 1
        else:
            if a_id < b_id:
                return -1
            elif a_id > b_id:
                return 1
    return 0
```

