import re

def gitignore_match(pattern, path):
    if not pattern:
        return False

    is_dir = path.endswith('/')
    if is_dir:
        path = path.rstrip('/')

    if pattern.endswith('/'):
        pattern = pattern.rstrip('/')
        if not is_dir:
            return False

    if pattern == '**':
        return True

    if pattern.startswith('/'):
        pattern = pattern[1:]
        anchored = True
    else:
        anchored = '/' in pattern

    if pattern == '**/':
        return True

    if pattern.endswith('/**'):
        prefix = pattern[:-3]
        if not prefix:
            return True
        if anchored:
            return path.startswith(prefix + '/') or path == prefix
        else:
            return '/' + path.startswith('/' + prefix + '/') or path == prefix or path.endswith('/' + prefix)

    if pattern.startswith('**/'):
        suffix = pattern[3:]
        if not suffix:
            return True
        if anchored:
            return path.endswith('/' + suffix) or path == suffix
        else:
            return path.endswith('/' + suffix) or path == suffix or ('/' + path).endswith('/' + suffix)

    if '**' in pattern:
        return False

    regex_parts = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            regex_parts.append('[^/]*')
        elif c == '?':
            regex_parts.append('[^/]')
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j < n:
                regex_parts.append(pattern[i:j+1])
                i = j
            else:
                regex_parts.append(re.escape(c))
        else:
            regex_parts.append(re.escape(c))
        i += 1

    regex = ''.join(regex_parts)
    if anchored:
        regex = '^' + regex + '$'
    else:
        regex = '(?:^|/)' + regex + '$'

    return re.match(regex, path) is not None
