def parse_range(header, size):
    if not header or not header.startswith('bytes='):
        return None
    ranges = []
    for part in header[6:].split(','):
        part = part.strip()
        if not part:
            continue
        if '-' not in part:
            return None
        start_str, end_str = part.split('-', 1)
        if start_str == '' and end_str == '':
            return None
        if start_str == '':
            try:
                suffix = int(end_str)
                if suffix < 0:
                    return None
                start = max(0, size - suffix)
                end = size - 1
                if start > end:
                    continue
                ranges.append((start, end))
            except ValueError:
                return None
        elif end_str == '':
            try:
                start = int(start_str)
                if start < 0:
                    return None
                if start >= size:
                    continue
                end = size - 1
                ranges.append((start, end))
            except ValueError:
                return None
        else:
            try:
                start = int(start_str)
                end = int(end_str)
                if start < 0 or end < 0 or start > end:
                    return None
                if start >= size:
                    continue
                end = min(end, size - 1)
                if start > end:
                    continue
                ranges.append((start, end))
            except ValueError:
                return None
    return ranges if ranges else None
