def unified_diff(a, b, context=3):
    def lcs(x, y):
        m, n = len(x), len(y)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                if x[i] == y[j]:
                    dp[i + 1][j + 1] = dp[i][j] + 1
                else:
                    dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])
        i, j = m, n
        res = []
        while i > 0 and j > 0:
            if x[i - 1] == y[j - 1]:
                res.append((i - 1, j - 1))
                i -= 1
                j -= 1
            elif dp[i - 1][j] >= dp[i][j - 1]:
                i -= 1
            else:
                j -= 1
        return list(reversed(res))

    matches = lcs(a, b)
    if not matches and not a and not b:
        return []

    diffs = []
    i = j = 0
    for ai, bj in matches:
        if i < ai or j < bj:
            diffs.append((i, ai, j, bj))
        i, j = ai + 1, bj + 1
    if i < len(a) or j < len(b):
        diffs.append((i, len(a), j, len(b)))

    if not diffs:
        return []

    hunks = []
    for a_start, a_end, b_start, b_end in diffs:
        hunk_a_start = max(0, a_start - context)
        hunk_a_end = min(len(a), a_end + context)
        hunk_b_start = max(0, b_start - context)
        hunk_b_end = min(len(b), b_end + context)
        hunks.append((hunk_a_start, hunk_a_end, hunk_b_start, hunk_b_end))

    merged = []
    for hunk in hunks:
        if not merged:
            merged.append(list(hunk))
        else:
            last = merged[-1]
            if hunk[0] <= last[1] and hunk[2] <= last[3]:
                last[1] = max(last[1], hunk[1])
                last[3] = max(last[3], hunk[3])
            else:
                merged.append(list(hunk))

    result = []
    for a_start, a_end, b_start, b_end in merged:
        a_len = a_end - a_start
        b_len = b_end - b_start
        result.append(f"@@ -{a_start + 1},{a_len} +{b_start + 1},{b_len} @@")
        for i in range(a_start, a_end):
            if i < len(a) and (i < b_start or i >= b_end or a[i] != b[i]):
                result.append(f"-{a[i]}")
            elif i < len(a):
                result.append(f" {a[i]}")
        for i in range(b_start, b_end):
            if i < len(b) and (i < a_start or i >= a_end or a[i] != b[i]):
                result.append(f"+{b[i]}")
            elif i < len(b):
                result.append(f" {b[i]}")
    return result
