import heapq

def topk(stream, k):
    if k <= 0:
        return []
    heap = []
    for idx, (value, label) in enumerate(stream):
        if len(heap) < k:
            heapq.heappush(heap, (value, idx, label))
        else:
            if value > heap[0][0] or (value == heap[0][0] and idx < heap[0][1]):
                heapq.heapreplace(heap, (value, idx, label))
    return [(v, l) for (v, _, l) in sorted(heap, key=lambda x: (-x[0], x[1]))]
