    def parse_field(field_str, min_val, max_val):
        if not field_str:
            raise ValueError("Empty field")
        parts = field_str.split(',')
        result = set()
        for part in parts:
            if '/' in part:
                base, step_str = part.split('/', 1)
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Invalid step: {step_str}")
                if step <= 0:
                    raise ValueError("Step must be positive")
