                    start_str, end_str = base.split('-', 1)
                    start = int(start_str)
                    end = int(end_str)
                except ValueError:
                    raise ValueError(f"Invalid range: {base}")
                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Range out of bounds or invalid: {base}")
            else:
