                    val = int(base)
                except ValueError:
                    raise ValueError(f"Invalid value: {base}")
                if val < min_val or val > max_val:
                    raise ValueError(f"Value out of bounds: {base}")
                start = end = val

            for v in range(start, end + 1, step):
