import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    dist = {}
    edges = {}
    prev = {}

    heap = [(0, 0, src, [src])]  # (cost, edge_count, node, path)

    while heap:
        cost, edge_count, node, path = heapq.heappop(heap)

        if node in dist:
            if cost > dist[node] or (cost == dist[node] and edge_count > edges[node]):
                continue

        dist[node] = cost
        edges[node] = edge_count
        prev[node] = path[:-1] if len(path) > 1 else []

        if node == dst:
            return (cost, path)

        for neighbor, weight in graph.get(node, []):
            new_cost = cost + weight
            new_edge_count = edge_count + 1
            new_path = path + [neighbor]

            if neighbor not in dist or new_cost < dist[neighbor] or (new_cost == dist[neighbor] and new_edge_count < edges[neighbor]):
                heapq.heappush(heap, (new_cost, new_edge_count, neighbor, new_path))

    return (None, [])

