import heapq

def topo_lex(graph):
    # Build set of all nodes
    nodes = set(graph.keys())
    for succs in graph.values():
        nodes.update(succs)

    # Compute in-degree: number of predecessors
    in_degree = {node: 0 for node in nodes}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    # Initialize heap with nodes having in-degree 0
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    return result if len(result) == len(nodes) else None

