function pLimit(n) {
  if (n < 1) throw new TypeError('Expected n to be a positive integer');
  let active = 0;
  const queue = [];
  let resolveQueue = null;

  const next = () => {
    if (queue.length === 0) {
      resolveQueue = null;
      return;
    }
    active++;
    const job = queue.shift();
    job()
      .finally(() => {
        active--;
        if (queue.length > 0) {
          next();
        } else if (resolveQueue) {
          resolveQueue();
        }
      });
  };

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push(() => fn().then(resolve, reject));
      if (active < n && resolveQueue === null) {
        next();
      }
    });
  };
}

module.exports = pLimit;
