class Emitter {
  constructor() {
    this._events = new Map();
  }

  on(event, fn) {
    if (!this._events.has(event)) this._events.set(event, []);
    const list = this._events.get(event);
    list.push({ fn, once: false });
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const unsubscribe = this.on(event, fn);
    const list = this._events.get(event);
    const last = list[list.length - 1];
    last.once = true;
    return unsubscribe;
  }

  off(event, fn) {
    if (!this._events.has(event)) return;
    const list = this._events.get(event);
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === fn) {
        list.splice(i, 1);
        if (list.length === 0) this._events.delete(event);
        break;
      }
    }
  }

  emit(event, ...args) {
    if (!this._events.has(event)) return 0;
    const snapshot = [...this._events.get(event)];
    let invoked = 0;
    const errors = [];

    for (const item of snapshot) {
      try {
        item.fn(...args);
        invoked++;
      } catch (err) {
        if (errors.length === 0) errors.push(err);
      }

      if (item.once) {
        this.off(event, item.fn);
      }
    }

    if (errors.length > 0) throw errors[0];
    return invoked;
  }
}

module.exports = Emitter;
