function sqlTag(strings, ...values) {
  let text = '';
  const allValues = [];
  let placeholderIndex = 1;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const value = values[i];
      if (value === null || value === undefined) {
        text += `$${placeholderIndex++}`;
        allValues.push(value);
      } else if (Array.isArray(value)) {
        if (value.length === 0) {
          text += '()';
        } else {
          text += '(';
          for (let j = 0; j < value.length; j++) {
            if (j > 0) text += ', ';
            text += `$${placeholderIndex++}`;
            allValues.push(value[j]);
          }
          text += ')';
        }
      } else if (typeof value === 'object' && value !== null && value.text !== undefined && value.values !== undefined) {
        // Inline sqlTag result
        const { text: innerText, values: innerValues } = value;
        text += innerText.replace(/\$(\d+)/g, (match, p1) => {
          const idx = parseInt(p1, 10) + placeholderIndex - 1;
          return `$${idx}`;
        });
        allValues.push(...innerValues);
        placeholderIndex += innerValues.length;
      } else {
        text += `$${placeholderIndex++}`;
        allValues.push(value);
      }
    }
  }

  return { text, values: allValues };
}

module.exports = sqlTag;
