function parseQuery(qs) {
  if (typeof qs !== 'string') return {};
  if (qs.startsWith('?')) qs = qs.slice(1);
  const result = {};
  const pairs = qs.split('&');
  for (const pair of pairs) {
    if (!pair) continue;
    const [key, value] = pair.split('=');
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = value === undefined ? '' : decodeURIComponent(value.replace(/\+/g, ' '));
    setNested(result, decodedKey, decodedValue);
  }
  return result;
}

function setNested(obj, key, value) {
  const match = key.match(/^([^\[\]]+)(?:\[(.*)\])?$/);
  if (!match) {
    obj[key] = value;
    return;
  }
  const [, base, rest] = match;
  if (rest === undefined) {
    if (obj[base] === undefined) {
      obj[base] = value;
    } else if (Array.isArray(obj[base])) {
      obj[base].push(value);
    } else {
      obj[base] = [obj[base], value];
    }
  } else {
    if (obj[base] === undefined) {
      obj[base] = rest === '' ? [] : {};
    } else if (Array.isArray(obj[base]) && rest === '') {
      // already an array, continue
    } else if (!Array.isArray(obj[base]) && typeof obj[base] !== 'object') {
      obj[base] = {};
    }
    setNested(obj[base], rest, value);
  }
}

function buildQuery(obj) {
  const pairs = [];
  function recurse(current, prefix) {
    for (const key in current) {
      if (!Object.prototype.hasOwnProperty.call(current, key)) continue;
      const value = current[key];
      const encodedKey = encodeURIComponent(key);
      const fullKey = prefix ? `${prefix}[${encodedKey}]` : encodedKey;
      if (value === null || value === undefined) {
        pairs.push(fullKey);
      } else if (Array.isArray(value)) {
        if (value.length === 0) {
          pairs.push(`${fullKey}[]`);
        } else {
          for (let i = 0; i < value.length; i++) {
            recurse(value[i], `${fullKey}[${i}]`);
          }
        }
      } else if (typeof value === 'object') {
        recurse(value, fullKey);
      } else {
        const encodedValue = encodeURIComponent(String(value));
        pairs.push(`${fullKey}=${encodedValue}`);
      }
    }
  }
  recurse(obj, '');
  return pairs.sort().join('&');
}

module.exports = { parseQuery, buildQuery };
