function toposortTasks(tasks) {
  const graph = {};
  const inDegree = {};
  const result = {};
  const pending = new Set();
  const errors = [];

  for (const [name, { deps }] of Object.entries(tasks)) {
    graph[name] = deps || [];
    inDegree[name] = 0;
  }

  for (const [name, { deps }] of Object.entries(tasks)) {
    for (const dep of deps) {
      if (!tasks[dep]) {
        throw new Error(`Unknown dependency: ${dep}`);
      }
      if (!graph[dep]) graph[dep] = [];
      graph[dep].push(name);
      inDegree[name]++;
    }
  }

  const queue = [];
  for (const [name, degree] of Object.entries(inDegree)) {
    if (degree === 0) queue.push(name);
  }

  let processed = 0;

  while (queue.length) {
    const name = queue.shift();
    processed++;

    const task = tasks[name];
    const depValues = {};
    for (const dep of task.deps || []) {
      depValues[dep] = result[dep];
    }

    const promise = task.run(depValues)
      .then(value => {
        result[name] = value;
        for (const neighbor of graph[name] || []) {
          inDegree[neighbor]--;
          if (inDegree[neighbor] === 0) queue.push(neighbor);
        }
      })
      .catch(err => {
        errors.push(err);
        for (const neighbor of graph[name] || []) {
          inDegree[neighbor]--;
          if (inDegree[neighbor] === 0) queue.push(neighbor);
        }
      });

    pending.add(promise);
  }

  if (processed !== Object.keys(tasks).length) {
    throw new Error('cycle detected in task dependencies');
  }

  return Promise.allSettled(Array.from(pending))
    .then(results => {
      for (const res of results) {
        if (res.status === 'rejected') {
          throw res.reason;
        }
      }
      return result;
    });
}

module.exports = { toposortTasks };
