export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Array<(payload: any) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers.has(k)) {
      this.handlers.set(k, []);
    }
    const list = this.handlers.get(k)!;
    list.push(fn as (payload: any) => void);
    return () => {
      const list = this.handlers.get(k);
      if (list) {
        const idx = list.indexOf(fn as (payload: any) => void);
        if (idx !== -1) list.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [E[K]]): void {
    const list = this.handlers.get(k);
    if (!list) return;
    for (const fn of list) {
      if (args.length === 0) {
        fn(undefined as any);
      } else {
        fn(args[0]);
      }
    }
  }
}
