type DiscriminatedUnion<T extends string, V extends Record<string, any>> = 
  { [K in keyof V]: { kind: T & K } & V[K] }[keyof V];

type Handlers<T extends string, V extends Record<string, any>, R> = 
  { [K in keyof V]: (value: { kind: T & K } & V[K]) => R };

function match<T extends string, V extends Record<string, any>, R>(
  value: DiscriminatedUnion<T, V>,
  handlers: Handlers<T, V, R>
): R {
  const handler = handlers[value.kind as keyof V];
